WITH valid_payments AS (SELECT * FROM payments WHERE status <> 'REFUNDED' AND paid_at < '2025-02-18' AND amount >= 750), agg AS (SELECT CASE WHEN amount >= 1290 THEN 'high' WHEN amount >= 370 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(amount) AS amount_count FROM valid_payments GROUP BY CASE WHEN amount >= 1290 THEN 'high' WHEN amount >= 370 THEN 'mid' ELSE 'low' END) SELECT amount_bucket, amount_count FROM agg
